def factors(value):
    factor_list = []
    divisor = 2
    while divisor * divisor <= value:
        while value % divisor == 0:
            factor_list.append(divisor)
            value //= divisor
        divisor = 3 if divisor == 2 else divisor + 2
    if value > 1:
        factor_list.append(value)
    return factor_list

