def proverb(*rhyme_items, qualifier):
    if not rhyme_items:
        return []
    phrases = [
        f'For want of a {cause} the {loss} was lost.'
        for cause, loss in zip(rhyme_items, rhyme_items[1:])
    ]
    first = rhyme_items[0]
    if qualifier:
        first = f'{qualifier} {first}'
    phrases.append(f'And all for the want of a {first}.')
    return phrases

