def rectangles(strings=''):
    total = 0
    for top_index, top in enumerate(strings):
        vertical = [cell == '+' for cell in top]
        for bottom_index in range(top_index + 1, len(strings)):
            bottom = strings[bottom_index]
            left_corners = 0
            for col, cell in enumerate(bottom):
                vertical[col] = vertical[col] and cell in '|+'
                if top[col] not in '-+' or cell not in '-+':
                    left_corners = 0
                elif vertical[col] and cell == '+':
                    total += left_corners
                    left_corners += 1
    return total

